class GameObjects {
    _time;
    _player;
    _cartCollection;
    _cartForUse;
    _cartRepository;
    _history; //TODO 
    setTime(time) {
        this._time = time;
        return this;
    }
    getTime() {
        return this._time;
    }
    setPlayer(player) {
        this._player = player;
        return this;
    }
    getPlayer() {
        return this._player;
    }
    setCartCollection(cartCollection) {
        this._cartCollection = cartCollection;
        return this;
    }
    getCartCollection() {
        return this._cartCollection;
    }
    setCartRepository(cartRepository) {
        this._cartRepository = cartRepository;
        return this;
    }
    getCartRepository() {
        return this._cartRepository;
    }
    setCartForUse(cartForUse) {
        this._cartForUse = cartForUse;
        return this;
    }
    getCartForUse() {
        return this._cartForUse;
    }
}
export default GameObjects;
